import{_ as o,o as i,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Invoices — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Invoices — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/invoices"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Invoices — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/invoices"}]]},"headers":[],"relativePath":"deployment/invoices.md","filePath":"deployment/invoices.md","lastUpdated":1786636213000}'),s={name:"deployment/invoices.md"};function a(c,e,r,l,d,m){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="invoices-—-production-guide" tabindex="-1">Invoices — Production Guide <a class="header-anchor" href="#invoices-—-production-guide" aria-label="Permalink to &quot;Invoices — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>invoices</code></li><li>Category: <strong>Billing</strong> (<code>billing</code>)</li><li><strong>Free Marketplace opt-in</strong> (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 10</code></li><li><strong>No hard dependency</strong> — unlike Quotations/Contracts, Invoices does <strong>not</strong> require Opportunities (or any other module) and can be installed standalone</li><li>The <strong>Payments</strong> module (shipped — see <a href="/deployment/payments">deployment/payments.md</a>) declares a required <code>module_dependencies</code> row on Invoices, so Invoices must be installed first before a workspace can enable Payments</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create:</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules only (Invoices is never auto-installed)</li><li>Operators enable Invoices from Marketplace at any time — no prerequisite module install order</li><li>Tenant permissions include <code>invoices.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Invoices permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code> (see <code>database/migrations/2026_07_31_220005_add_invoices_permissions.php</code>). Do <strong>not</strong> re-seed roles.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>customer_invoice_created</code>, <code>customer_invoice_updated</code>, <code>customer_invoice_deleted</code>, <code>customer_invoice_assigned</code>, <code>customer_invoice_status_changed</code>, <code>customer_invoice_note_added</code></li><li>Notifications: assignment via <code>CustomerInvoiceAssignedNotification</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>customer_invoices</code>, <code>customer_invoice_lines</code>, <code>customer_invoice_notes</code>, <code>customer_invoice_activities</code>)</li><li>Register the <code>invoices</code> catalog module via migration (<code>DefaultModuleRegistrar</code>) as free Billing opt-in — <strong>not</strong> <code>db:seed</code></li><li>Run invoices permissions migration so default roles receive missing <code>invoices.*</code> grants</li><li>Confirm <code>module:invoices</code> + <code>invoices.*</code> permissions on target roles</li><li>Deploy Frontend SPA with Invoices nav (new <strong>Billing</strong> sidebar group)/pages (mirror Quotations table + form) when the SPA ships</li><li>Payments (shipped) declares a <code>module_dependencies</code> row on <code>invoices</code> — confirm it blocks install on workspaces without Invoices entitled (see <a href="/deployment/payments">deployment/payments.md</a>)</li></ol>',12)])])}const g=o(s,[["render",a]]);export{u as __pageData,g as default};
